with flagged as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval 1 hour then 1 else 0 end as is_new_burst from device_readings), islands as (select *, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged) select date_trunc('day', reading_ts) as activity_day, percentile_approx(is_new_burst, array(0.25, 0.5, 0.75)) as is_new_burst_quartiles, count(*) filter (where device_code = 'DV-01') as dv_01_rows from islands group by date_trunc('day', reading_ts)
